Ltac brute_regZ0 n r lo cnt g :=
  let w := getreg n in
  lazymatch w with
  | Z_to_bv 64 ?e =>
      let F := eval pattern r in e in
      lazymatch F with
      | ?f r =>
          let H := fresh "BR" in
          assert (H : forall r0, lo <= r0 < lo + cnt -> (f r0 =? g r0) = true)
            by (apply (brute_range (fun r0 => f r0 =? g r0) lo cnt); vm_compute; reflexivity);
          replace e with (g r) by (symmetry; apply Z.eqb_eq; apply H; lia);
          clear H
      end
  | _ => fail "brute_regZ0: register" n "holds" w
  end.

Ltac ztoF pc := repeat (lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

(* [comment removed for export] *)
Ltac afa_popc_tac P r :=
  let p := eval vm_compute in (P + 12) in ztoF p; brute_regZ0 11%Z r 1 255 sm1;
  let p := eval vm_compute in (P + 24) in ztoF p; brute_regZ0 11%Z r 1 255 sm2;
  let p := eval vm_compute in (P + 32) in ztoF p; brute_regZ0 11%Z r 1 255 sm3;
  let p := eval vm_compute in (P + 36) in ztoF p; brute_regZ0 11%Z r 1 255 nsm;
  let p := eval vm_compute in (P + 56) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_a (nsm r0));
  let p := eval vm_compute in (P + 76) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_b (pc_a (nsm r0)));
  let p := eval vm_compute in (P + 84) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_c (pc_b (pc_a (nsm r0))));
  let p := eval vm_compute in (P + 104) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_d (pc_c (pc_b (pc_a (nsm r0)))));
  let p := eval vm_compute in (P + 108) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => 31 - Z.log2 r0);
  let p := eval vm_compute in (P + 112) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => Z.log2 r0);
  let p := eval vm_compute in (P + 120) in ztoF p; brute_regZ0 14%Z r 1 255 (fun r0 => 8 - Z.log2 r0);
  zstep.

